import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { IonicModule } from '@ionic/angular';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { AccountInterceptor } from '../../../core/utility/account.interceptor';
import { PriceModule } from '../../../core/pipe/price.module';
import { RouterModule } from '@angular/router';
import { ArticleService } from '../../../data/service/article/article.service';
import { ArticleComponent } from './article/article.component';
import { TeacherArticleComponent } from './teacher-article/teacher-article.component';
import { ProductArticleComponent } from './product-article/product-article.component';
import { SellerArticleComponent } from './seller-article/seller-article.component';



@NgModule({
  declarations: [ArticleComponent, TeacherArticleComponent, ProductArticleComponent, SellerArticleComponent],
  imports: [
    CommonModule,
    IonicModule,
    HttpClientModule,
    RouterModule,
    PriceModule
  ],
  providers: [
    ArticleService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ],
  exports: [ArticleComponent, TeacherArticleComponent, ProductArticleComponent, SellerArticleComponent]
})
export class SharedArticleModule { }
