import { IArticleModel } from './ArticleModel';

export interface IArticleFilterModel {

    title: string;
    articles: IArticleModel[];

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;
}

export class ArticleFilterModel implements IArticleFilterModel {

    title: string;
    articles: IArticleModel[];

    // Base Page
    pageId: number;
    pageCount: number;
    activePage: number;
    startPage: number;
    endPage: number;
    takeEntity: number;
    skipEntity: number;

    constructor(
        pageId?: number,
        takeEntity?: number,
        title?: string) {

        if (+takeEntity > 36) {
            this.takeEntity = 36;
        }
        else if (+takeEntity < 1) {
            this.takeEntity = 1;
        }
        else {
            this.takeEntity = takeEntity ? +takeEntity : 6;
        }

        this.pageId = pageId ? +pageId : 1;
        this.title = title ? title : null;
    }
}
