import { Component, Input, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { G } from 'src/app/core/common/G';
import { IArticleModel } from 'src/app/data/model/article/ArticleModel';

@Component({
  selector: 'app-product-article',
  templateUrl: './product-article.component.html',
  styleUrls: ['./product-article.component.scss']
})
export class ProductArticleComponent implements OnInit {

  @Input() article: IArticleModel;
  windowWidth = 1000;

  constructor(private router: Router) {
    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  ngOnInit(): void {
  }

  onClick() {

    this.router
      .navigate(
        ['/pa', this.article.id]);
  }
}
