import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { IArticleModel } from 'src/app/data/model/article/ArticleModel';

@Component({
  selector: 'app-seller-article',
  templateUrl: './seller-article.component.html',
  styleUrls: ['./seller-article.component.scss']
})
export class SellerArticleComponent implements OnInit {

  @Input() article: IArticleModel;
  @Output() SelectEvent = new EventEmitter<string | number>();
  @Output() SelectEvent2 = new EventEmitter<IArticleModel>();

  constructor() { }

  ngOnInit(): void {
  }

  onClick() {
    this.SelectEvent.emit(this.article.id);
    this.SelectEvent2.emit(this.article);
  }
}
